module cluster_min #(\n    parameter MAX_N = 16,\n    parameter DATA_WIDTH = 8,\n    parameter STATE_WIDTH = 4\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [DATA_WIDTH-1:0] a [0:MAX_N-1],\n    input wire [DATA_WIDTH-1:0] b [0:MAX_N-1],\n    input wire [MAX_N-1:0] c,\n    input wire [3:0] n,\n    output reg [DATA_WIDTH*2:0] result,\n    output reg done\n);\n\n    // State machine definitions\n    localparam [STATE_WIDTH-1:0] S_IDLE            = 4'd0;\n    localparam [STATE_WIDTH-1:0] S_INIT            = 4'd1;\n    localparam [STATE_WIDTH-1:0] S_PREPARE_PAIRS   = 4'd2;\n    localparam [STATE_WIDTH-1:0] S_COMPUTE_PAIR    = 4'd3;\n    localparam [STATE_WIDTH-1:0] S_LOOP_NON_VOTERS = 4'd4;\n    localparam [STATE_WIDTH-1:0] S_UPDATE_MIN      = 4'd5;\n    localparam [STATE_WIDTH-1:0] S_DONE            = 4'd6;\n\n    reg [STATE_WIDTH-1:0] state, next_state;\n\n    // Internal storage\n    reg [DATA_WIDTH-1:0] a_reg [0:MAX_N-1];\n    reg [DATA_WIDTH-1:0] b_reg [0:MAX_N-1];\n    reg [MAX_N-1:0] c_reg;\n    reg [3:0] n_reg;\n\n    // Computation registers\n    reg [3:0] k;\n    reg [3:0] m;\n    reg [3:0] voter_idx [0:MAX_N-1];\n    reg [3:0] non_voter_idx [0:MAX_N-1];\n    reg [3:0] i, j;\n    reg [3:0] p;\n    reg signed [DATA_WIDTH-1:0] ax, ay, bx, by;\n    reg signed [DATA_WIDTH-1:0] dx, dy;\n    reg [DATA_WIDTH*2-1:0] dot_uw;\n    reg signed [DATA_WIDTH*2:0] dot_pu;\n    reg [DATA_WIDTH*2:0] count;\n    reg [DATA_WIDTH*2:0] cluster_size;\n    reg [DATA_WIDTH*2:0] min_cluster;\n\n    // Cycle counter for safety\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd200;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            S_IDLE: begin\n                if (start) next_state = S_INIT;\n            end\n            S_INIT: next_state = S_PREPARE_PAIRS;\n            S_PREPARE_PAIRS: next_state = S_COMPUTE_PAIR;\n            S_COMPUTE_PAIR: next_state = S_LOOP_NON_VOTERS;\n            S_LOOP_NON_VOTERS: begin\n                if (p < m) next_state = S_LOOP_NON_VOTERS;\n                else next_state = S_UPDATE_MIN;\n            end\n            S_UPDATE_MIN: begin\n                if (j < k-1) next_state = S_COMPUTE_PAIR;\n                else if (i < k-1) next_state = S_PREPARE_PAIRS;\n                else next_state = S_DONE;\n            end\n            S_DONE: next_state = S_IDLE;\n            default: next_state = S_IDLE;\n        endcase\n    end\n\n    // Datapath and control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= {(DATA_WIDTH*2+1){1'b0}};\n            cycle_count <= 8'd0;\n            k <= 4'd0;\n            m <= 4'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            p <= 4'd0;\n            min_cluster <= {(DATA_WIDTH*2+1){1'b0}};\n            cluster_size <= {(DATA_WIDTH*2+1){1'b0}};\n            count <= {(DATA_WIDTH*2+1){1'b0}};\n\n            // Initialize arrays\n            for (integer idx = 0; idx < MAX_N; idx = idx + 1) begin\n                voter_idx[idx] <= 4'd0;\n                non_voter_idx[idx] <= 4'd0;\n                a_reg[idx] <= {DATA_WIDTH{1'b0}};\n                b_reg[idx] <= {DATA_WIDTH{1'b0}};\n            end\n\n            c_reg <= {MAX_N{1'b0}};\n            n_reg <= 4'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        // Capture inputs\n                        for (integer idx = 0; idx < MAX_N; idx = idx + 1) begin\n                            a_reg[idx] <= a[idx];\n                            b_reg[idx] <= b[idx];\n                        end\n                        c_reg <= c;\n                        n_reg <= n;\n                    end\n                end\n\n                S_INIT: begin\n                    k <= 4'd0;\n                    m <= 4'd0;\n                    for (integer idx = 0; idx < n_reg; idx = idx + 1) begin\n                        if (c_reg[idx]) begin\n                            voter_idx[k] <= idx[3:0];\n                            k <= k + 4'd1;\n                        end else begin\n                            non_voter_idx[m] <= idx[3:0];\n                            m <= m + 4'd1;\n                        end\n                    end\n                    min_cluster <= {1'b0, k, {DATA_WIDTH*2-4{1'b0}}};  // k extended to result width\n                end\n\n                S_PREPARE_PAIRS: begin\n                    i <= 4'd0;\n                    j <= 4'd1;  // Start with j = i+1\n                end\n\n                S_COMPUTE_PAIR: begin\n                    ax <= a_reg[voter_idx[i]];\n                    ay <= b_reg[voter_idx[i]];\n                    bx <= a_reg[voter_idx[j]];\n                    by <= b_reg[voter_idx[j]];\n                    dx <= bx - ax;\n                    dy <= by - ay;\n                    dot_uw <= (bx - ax)*(bx - ax) + (by - ay)*(by - ay);\n                    count <= {(DATA_WIDTH*2+1){1'b0}};\n                    p <= 4'd0;\n                end\n\n                S_LOOP_NON_VOTERS: begin\n                    if (p < m) begin\n                        dot_pu <= (a_reg[non_voter_idx[p]] - ax) * dx + \n                                  (b_reg[non_voter_idx[p]] - ay) * dy;\n\n                        if (dot_pu > $signed(0) && dot_pu < $signed(dot_uw)) begin\n                            count <= count + (DATA_WIDTH*2+1)'d1;\n                        end\n\n                        p <= p + 4'd1;\n                    end\n                end\n\n                S_UPDATE_MIN: begin\n                    cluster_size <= {1'b0, k, {DATA_WIDTH*2-4{1'b0}}} + count;\n                    if (cluster_size < min_cluster) begin\n                        min_cluster <= cluster_size;\n                    end\n\n                    if (j < k - 4'd1) begin\n                        j <= j + 4'd1;\n                    end else begin\n                        j <= i + 4'd2;\n                        if (i < k - 4'd2) begin\n                            i <= i + 4'd1;\n                        end\n                    end\n                end\n\n                S_DONE: begin\n                    result <= min_cluster;\n                    done <= 1'b1;\n                end\n            endcase\n\n            // Cycle counter\n            if (state != S_IDLE) begin\n                cycle_count <= cycle_count + 8'd1;\n                if (cycle_count >= MAX_CYCLES) begin\n                    next_state = S_DONE;  // Force completion if timeout\n                end\n            end\n        end\n    end\n\nendmodule